1	// Offline route resolution: match a request against configured route prefixes
2	// and join the remainder onto the upstream base path without any network I/O.
3	package contractsentinel
4	
5	import (
6		"bytes"
7		"encoding/json"
8		"fmt"
9		"net/url"
10		"sort"
11		"strings"
12	)
13	
14	// Route is one configured route: an id, accepted methods, a path prefix and
15	// the upstream URL requests on that route are forwarded to. An optional
16	// queryTransforms list rewrites the request query string after the route has
17	// been selected.
18	type Route struct {
19		ID              string            `json:"id"`
20		Methods         []string          `json:"methods"`
21		PathPrefix      string            `json:"pathPrefix"`
22		Upstream        string            `json:"upstream"`
23		QueryTransforms []*QueryTransform `json:"-"`
24	}
25	
26	// QueryTransform is one rule in a route's queryTransforms array: op is
27	// "set" or "remove", name is matched against decoded parameter names, and
28	// value (set only) is used literally.
29	type QueryTransform struct {
30		Op    string `json:"op"`
31		Name  string `json:"name"`
32		Value string `json:"value"`
33	}
34	
35	// routeJSON mirrors Route, keeping queryTransforms as raw JSON so null,
36	// wrong types and malformed rules can be reported with the route's location
37	// instead of as a generic decode error.
38	type routeJSON struct {
39		ID              string          `json:"id"`
40		Methods         []string        `json:"methods"`
41		PathPrefix      string          `json:"pathPrefix"`
42		Upstream        string          `json:"upstream"`
43		QueryTransforms json.RawMessage `json:"queryTransforms"`
44	}
45	
46	// UnmarshalJSON decodes a route object and eagerly validates its
47	// queryTransforms (if present); the location matches ParseConfig's
48	// "route N" numbering so the reason can identify the route and rule.
49	func (route *Route) UnmarshalJSON(data []byte) error {
50		var rj routeJSON
51		if err := json.Unmarshal(data, &rj); err != nil {
52			return err
53		}
54		idx := routeUnmarshalIndex
55		routeUnmarshalIndex++
56		route.ID = rj.ID
57		route.Methods = rj.Methods
58		route.PathPrefix = rj.PathPrefix
59		route.Upstream = rj.Upstream
60	
61		if len(rj.QueryTransforms) == 0 {
62			return nil // field absent
63		}
64		loc := fmt.Sprintf("route %d", idx+1)
65		transforms, f := parseQueryTransforms(rj.QueryTransforms, loc, rj.ID)
66		if f != nil {
67			return f
68		}
69		route.QueryTransforms = transforms
70		return nil
71	}
72	
73	// parseQueryTransforms decodes and validates the raw queryTransforms array
74	// of one route. loc identifies the route; rule errors additionally carry a
75	// 1-based rule index.
76	func parseQueryTransforms(raw json.RawMessage, loc, id string) ([]*QueryTransform, *Failure) {
77		body := strings.TrimSpace(string(raw))
78		if body == "null" {
79			return nil, failuref("invalid_config", "%s: queryTransforms must not be null", routeLabel(loc, id))
80		}
81		var elems []json.RawMessage
82		if err := json.Unmarshal([]byte(body), &elems); err != nil {
83			return nil, failuref("invalid_config", "%s: queryTransforms must be an array", routeLabel(loc, id))
84		}
85		transforms := make([]*QueryTransform, 0, len(elems))
86		for i, elem := range elems {
87			ruleLoc := fmt.Sprintf("%s, queryTransforms rule %d", routeLabel(loc, id), i+1)
88			if string(bytes.TrimSpace(elem)) == "null" {
89				return nil, failuref("invalid_config", "%s: rule must not be null", ruleLoc)
90			}
91			var fields map[string]json.RawMessage
92			if err := json.Unmarshal(elem, &fields); err != nil {
93				return nil, failuref("invalid_config", "%s: rule must be a JSON object", ruleLoc)
94			}
95	
96			qt := &QueryTransform{}
97			opRaw, ok := fields["op"]
98			switch {
99			case !ok:
100				return nil, failuref("invalid_config", "%s: op is required", ruleLoc)
101			case !jsonString(opRaw, &qt.Op):
102				return nil, failuref("invalid_config", "%s: op must be a string", ruleLoc)
103			case qt.Op != "set" && qt.Op != "remove":
104				return nil, failuref("invalid_config", "%s: unknown op %q (only set and remove are supported)", ruleLoc, qt.Op)
105			}
106	
107			nameRaw, ok := fields["name"]
108			switch {
109			case !ok:
110				return nil, failuref("invalid_config", "%s: name is required", ruleLoc)
111			case !jsonString(nameRaw, &qt.Name):
112				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
113			case qt.Name == "":
114				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
115			}
116	
117			valueRaw, hasValue := fields["value"]
118			switch qt.Op {
119			case "set":
120				if !hasValue {
121					return nil, failuref("invalid_config", "%s: set requires a string value", ruleLoc)
122				}
123				if !jsonString(valueRaw, &qt.Value) {
124					return nil, failuref("invalid_config", "%s: value must be a string", ruleLoc)
125				}
126			case "remove":
127				if hasValue {
128					return nil, failuref("invalid_config", "%s: remove must not include a value", ruleLoc)
129				}
130			}
131			transforms = append(transforms, qt)
132		}
133		return transforms, nil
134	}
135	
136	// jsonString decodes raw into s and reports whether raw is a JSON string
137	// (null, numbers, objects and arrays fail).
138	func jsonString(raw json.RawMessage, s *string) bool {
139		if len(raw) == 0 || raw[0] != '"' {
140			return false
141		}
142		return json.Unmarshal(raw, s) == nil
143	}
144	
145	// routeLabel renders the human-readable route location, adding the id when
146	// the configuration supplied one.
147	func routeLabel(loc, id string) string {
148		if id != "" {
149			return fmt.Sprintf("%s (id %q)", loc, id)
150		}
151		return loc
152	}
153	
154	// routeUnmarshalIndex is advanced while a config is decoded so nested route
155	// unmarshalling can report its 1-based position. Route objects only occur in
156	// the routes array; ParseConfig resets it before each decode.
157	var routeUnmarshalIndex int
158	
159	// Config is the resolve configuration: a flat array of routes.
160	type Config struct {
161		Routes []Route `json:"routes"`
162	}
163	
164	// Request is one resolution request: an HTTP method and a request target
165	// (path with an optional raw query string).
166	type Request struct {
167		Method string `json:"method"`
168		Target string `json:"target"`
169	}
170	
171	// Resolution is the successful result of matching a request.
172	type Resolution struct {
173		RouteID     string `json:"routeId"`
174		UpstreamURL string `json:"upstreamURL"`
175	}
176	
177	// Failure carries a stable machine-readable code and a human-readable reason.
178	type Failure struct {
179		Code       string   `json:"code"`
180		Reason     string   `json:"reason"`
181		Candidates []string `json:"candidates,omitempty"`
182	}
183	
184	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
185	
186	func failuref(code, format string, args ...any) *Failure {
187		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
188	}
189	
190	// ParseConfig parses and fully validates the route configuration.
191	func ParseConfig(data []byte) (*Config, *Failure) {
192		var cfg Config
193		routeUnmarshalIndex = 0
194		if err := json.Unmarshal(data, &cfg); err != nil {
195			if f, ok := err.(*Failure); ok {
196				return nil, f
197			}
198			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
199		}
200		if f := cfg.validate(); f != nil {
201			return nil, f
202		}
203		return &cfg, nil
204	}
205	
206	func (cfg *Config) validate() *Failure {
207		seenIDs := make(map[string]int, len(cfg.Routes))
208		for i := range cfg.Routes {
209			route := &cfg.Routes[i]
210			loc := fmt.Sprintf("route %d", i+1)
211			if route.ID == "" {
212				return failuref("invalid_config", "%s: id must be non-empty", loc)
213			}
214			if first, ok := seenIDs[route.ID]; ok {
215				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
216			}
217			seenIDs[route.ID] = i + 1
218	
219			if len(route.Methods) == 0 {
220				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
221			}
222			for _, method := range route.Methods {
223				switch {
224				case method == "":
225					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
226				case method == "*":
227					// Wildcard matching any legal method.
228				case !isToken(method):
229					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
230				}
231			}
232	
233			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
234				return f
235			}
236			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
237				return f
238			}
239		}
240		return nil
241	}
242	
243	func validatePrefix(prefix, loc, id string) *Failure {
244		switch {
245		case prefix == "" || prefix[0] != '/':
246			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
247		case prefix != "/" && strings.HasSuffix(prefix, "/"):
248			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
249		case strings.ContainsAny(prefix, "?#"):
250			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
251		case !validPercentEscapes(prefix):
252			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
253		}
254		return nil
255	}
256	
257	func validateUpstream(raw, loc, id string) *Failure {
258		if strings.ContainsAny(raw, "?#") {
259			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
260		}
261		u, err := url.Parse(raw)
262		if err != nil {
263			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
264		}
265		if u.Scheme != "http" && u.Scheme != "https" {
266			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
267		}
268		if u.Host == "" {
269			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
270		}
271		return nil
272	}
273	
274	// ParseRequest parses and validates one JSON request.
275	func ParseRequest(data []byte) (*Request, *Failure) {
276		var req Request
277		if err := json.Unmarshal(data, &req); err != nil {
278			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
279		}
280		switch {
281		case req.Method == "":
282			return nil, failuref("invalid_request", "method is required")
283		case !isToken(req.Method):
284			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
285		}
286		switch {
287		case req.Target == "" || req.Target[0] != '/':
288			return nil, failuref("invalid_request", "target must start with /")
289		case strings.Contains(req.Target, "#"):
290			return nil, failuref("invalid_request", "target must not contain a fragment")
291		case !validPercentEscapes(req.Target):
292			return nil, failuref("invalid_request", "target contains an invalid percent escape")
293		}
294		return &req, nil
295	}
296	
297	// Resolve matches a validated request against a validated configuration and
298	// computes the upstream URL. Failure codes are route_not_found and
299	// route_conflict.
300	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
301		path := req.Target
302		if i := strings.IndexByte(path, '?'); i >= 0 {
303			path = path[:i]
304		}
305	
306		type candidate struct {
307			route    *Route
308			concrete bool
309		}
310		var matched []candidate
311		for i := range cfg.Routes {
312			route := &cfg.Routes[i]
313			concrete, wildcard := methodMatch(route.Methods, req.Method)
314			if !concrete && !wildcard {
315				continue
316			}
317			if !prefixMatch(route.PathPrefix, path) {
318				continue
319			}
320			matched = append(matched, candidate{route, concrete})
321		}
322		if len(matched) == 0 {
323			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
324		}
325	
326		// Longest prefix wins.
327		bestLen := 0
328		for _, c := range matched {
329			if n := len(c.route.PathPrefix); n > bestLen {
330				bestLen = n
331			}
332		}
333		winners := matched[:0]
334		for _, c := range matched {
335			if len(c.route.PathPrefix) == bestLen {
336				winners = append(winners, c)
337			}
338		}
339	
340		// Among equal prefixes a concrete method beats the wildcard.
341		var concrete []candidate
342		for _, c := range winners {
343			if c.concrete {
344				concrete = append(concrete, c)
345			}
346		}
347		if len(concrete) > 0 {
348			winners = concrete
349		}
350		if len(winners) > 1 {
351			ids := make([]string, 0, len(winners))
352			for _, c := range winners {
353				ids = append(ids, c.route.ID)
354			}
355			sort.Strings(ids)
356			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
357			f.Candidates = ids
358			return nil, f
359		}
360	
361		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
362		if f != nil {
363			return nil, f
364		}
365		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
366	}
367	
368	// methodMatch reports whether the method list matches the request method
369	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
370	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
371		for _, m := range methods {
372			switch {
373			case m == "*":
374				wildcard = true
375			case m == method:
376				concrete = true
377			}
378		}
379		return concrete, wildcard
380	}
381	
382	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
383	// treated as a separator and the root prefix matches every origin-path.
384	func prefixMatch(prefix, path string) bool {
385		if prefix == "/" {
386			return true
387		}
388		if path == prefix {
389			return true
390		}
391		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
392	}
393	
394	// joinUpstream strips the route prefix from the request path and joins the
395	// remainder onto the upstream base path with exactly one slash at the
396	// junction. The base path is carried over byte for byte: joining never
397	// re-encodes, reorders or drops anything outside that junction. The raw
398	// query is preserved verbatim unless the route defines queryTransforms, in
399	// which case they rewrite it after route selection.
400	func joinUpstream(route *Route, path, target string) (string, *Failure) {
401		if _, err := url.Parse(route.Upstream); err != nil {
402			// Config validation already rejected this.
403			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
404		}
405	
406		var remainder string
407		switch {
408		case route.PathPrefix == "/":
409			// Root keeps the whole following path; "/" itself has an empty remainder.
410			if path != "/" {
411				remainder = path
412			}
413		default:
414			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
415		}
416	
417		// Slice the validated upstream raw so nothing outside the junction is
418		// normalized or re-escaped (scheme://[userinfo@]host[/base-path]).
419		schemeEnd := strings.Index(route.Upstream, "://")
420		tail := route.Upstream[schemeEnd+3:]
421		hostPart, basePath := tail, ""
422		if i := strings.IndexByte(tail, '/'); i >= 0 {
423			hostPart, basePath = tail[:i], tail[i:]
424		}
425		joined := strings.TrimSuffix(basePath, "/")
426		if remainder == "" {
427			joined += "/" // the junction slash is kept even with no remaining path
428		} else {
429			joined += remainder
430		}
431	
432		result := route.Upstream[:schemeEnd+3] + hostPart + joined
433		query, f := applyQueryTransforms(route.QueryTransforms, target)
434		if f != nil {
435			return "", f
436		}
437		return result + query, nil
438	}
439	
440	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
441	func isToken(s string) bool {
442		if s == "" {
443			return false
444		}
445		for i := 0; i < len(s); i++ {
446			if !isTokenChar(s[i]) {
447				return false
448			}
449		}
450		return true
451	}
452	
453	func isTokenChar(c byte) bool {
454		switch {
455		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
456			return true
457		}
458		switch c {
459		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
460			return true
461		}
462		return false
463	}
464	
465	// validPercentEscapes checks that every "%' is followed by two hex digits.
466	// Matching and joining stay on raw strings, but malformed escapes are rejected
467	// up front for both prefixes and request targets.
468	func validPercentEscapes(s string) bool {
469		for i := 0; i < len(s); i++ {
470			if s[i] != '%' {
471				continue
472			}
473			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
474				return false
475			}
476			i += 2
477		}
478		return true
479	}
480	
481	func isHex(c byte) bool {
482		switch {
483		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
484			return true
485		}
486		return false
487	}
488

