32	func TestQueryTransformSet(t *testing.T) {
33		cases := []struct {
34			name      string
35			rules     string
36			target    string
37			wantQuery string // expected suffix after http://h.internal/base/p
38		}{
39			{
40				name:      "set merges all duplicates at first hit",
41				rules:     `[{"op":"set","name":"a","value":"9"}]`,
42				target:    "/p?z=0&a=1&a=2&b=3",
