67				wantQuery: "?flag=",
68			},
69			{
70				name:      "set appends an absent name at the end",
71				rules:     `[{"op":"set","name":"new","value":"v"}]`,
72				target:    "/p?a=1&b=2",
73				wantQuery: "?a=1&b=2&new=v",
74			},
75			{
76				name:      "set appends after an empty trailing fragment",
77				rules:     `[{"op":"set","name":"n","value":"v"}]`,
78				target:    "/p?a=1&",
79				wantQuery: "?a=1&&n=v",
80			},
81			{
82				name:      "set creates a query string when there is none",
83				rules:     `[{"op":"set","name":"a","value":"1"}]`,
84				target:    "/p",
85				wantQuery: "?a=1",
86			},
87			{
88				name:      "set on empty question mark adds the parameter",
89				rules:     `[{"op":"set","name":"a","value":"1"}]`,
90				target:    "/p?",
91				wantQuery: "?a=1",
92			},
93			{
94				name:      "set is case sensitive",
95				rules:     `[{"op":"set","name":"A","value":"2"}]`,
96				target:    "/p?a=1",
97				wantQuery: "?a=1&A=2",
98			},
99			{
100				name:      "set encodes spaces utf8 and reserved characters",
101				rules:     `[{"op":"set","name":"k y","value":"héllo /&=?"}]`,
102				target:    "/p",
103				wantQuery: "?k%20y=h%C3%A9llo%20%2F%26%3D%3F",
104			},
105			{
106				name:      "set keeps unreserved characters raw",
107				rules:     `[{"op":"set","name":"a-b_c.d~e","value":"-._~"}]`,
108				target:    "/p",
109				wantQuery: "?a-b_c.d~e=-._~",
110			},
111			{
112				name:      "set uses value literally including an equals sign",
113				rules:     `[{"op":"set","name":"a","value":"x=y"}]`,
114				target:    "/p?a=old",
115				wantQuery: "?a=x%3Dy",
116			},
117			{
118				name:      "unmodified values keep their original lowercase escapes",
119				rules:     `[{"op":"set","name":"a","value":""}]`,
120				target:    "/p?x=%2f&a=1",
121				wantQuery: "?x=%2f&a=",
122			},
123			{
124				name:      "rules chain on the previous result",
125				rules:     `[{"op":"set","name":"a","value":"1"},{"op":"set","name":"a","value":"2"}]`,
126				target:    "/p",
