153	func TestQueryTransformRemove(t *testing.T) {
154		cases := []struct {
155			name      string
156			ruleName  string
157			target    string
158			wantQuery string
159		}{
160			{"removes every parameter with the name", "a", "/p?a=1&b=2&a=3", "?b=2"},
161			{"removes a parameter without an equals sign", "flag", "/p?flag&a=1", "?a=1"},
162			{"matches decoded names", "a", "/p?%61=1&b=2", "?b=2"},
163			{"matches plus as space", "a b", "/p?a+b=1", ""},
164			{"does not match different case", "A", "/p?A=1&a=2", "?a=2"},
165			{"no hit leaves everything verbatim", "z", "/p?a=1&b=2", "?a=1&b=2"},
166			{"no hit leaves an empty question mark", "z", "/p?", "?"},
167			{"removing the last fragment drops the question mark", "a", "/p?a=1", ""},
168			{"removing params keeps surviving empty fragments and the mark", "a", "/p?a=1&&b=2", "?&b=2"},
169			{"removing the last param but an empty fragment remains keeps the mark", "a", "/p?a=1&", "?"},
170			{"removing params between empty fragments keeps their order", "a", "/p?&&a=1&&", "?&&&"},
171			{"with no query string remove does not add a mark", "a", "/p", ""},
172		}
173		for _, tc := range cases {
174			t.Run(tc.name, func(t *testing.T) {
175				rules := `[{"op":"remove","name":` + encodeJSONString(tc.ruleName) + `}]`
