191	// buildWant joins the expected query suffix onto the transformed target path.
192	func buildWant(target, wantQuery string) string {
193		base := "http://h.internal/base"
194		path := target
195		if q := strings.IndexByte(target, '?'); q >= 0 {
196			path = target[:q]
197		}
