246	func TestQueryTransformInvalidConfig(t *testing.T) {
247		good := `"id":"r1","methods":["*"],"pathPrefix":"/","upstream":"http://h"`
248		cases := []struct {
249			name    string
250			partial string // raw JSON of the queryTransforms field
251			want    string // reason substring
252			ruleErr bool   // whether the error names a rule (vs. the array itself)
253		}{
254			{"array null", `null`, "must not be null", false},
255			{"array wrong type", `{}`, "must be an array", false},
256			{"array is a string", `"x"`, "must be an array", false},
257			{"rule null", `[null]`, "rule must not be null", true},
258			{"rule not object", `[42]`, "rule must be a JSON object", true},
259			{"missing op", `[{"name":"a"}]`, "op is required", true},
260			{"op wrong type", `[{"op":1,"name":"a"}]`, "op must be a string", true},
261			{"unknown op", `[{"op":"delete","name":"a"}]`, "unknown op", true},
262			{"missing name", `[{"op":"remove"}]`, "name is required", true},
263			{"name wrong type", `[{"op":"remove","name":1}]`, "name must be a non-empty string", true},
264			{"name null", `[{"op":"remove","name":null}]`, "name must be a non-empty string", true},
265			{"empty name", `[{"op":"remove","name":""}]`, "name must be a non-empty string", true},
266			{"set missing value", `[{"op":"set","name":"a"}]`, "set requires a string value", true},
267			{"set null value", `[{"op":"set","name":"a","value":null}]`, "value must be a string", true},
268			{"set numeric value", `[{"op":"set","name":"a","value":1}]`, "value must be a string", true},
269			{"remove with value", `[{"op":"remove","name":"a","value":"x"}]`, "remove must not include a value", true},
270			{"remove with empty value still rejected", `[{"op":"remove","name":"a","value":""}]`, "remove must not include a value", true},
271		}
272		for _, tc := range cases {
273			t.Run(tc.name, func(t *testing.T) {
274				src := `{"routes":[{` + good + `,"queryTransforms":` + tc.partial + `}]}`
275				_, f := ParseConfig([]byte(src))
276				if f == nil {
277					t.Fatalf("expected invalid_config")
278				}
279				if f.Code != "invalid_config" {
280					t.Fatalf("code = %q, want invalid_config", f.Code)
281				}
282				if !strings.Contains(f.Reason, "route 1") {
283					t.Fatalf("reason = %q should locate route 1", f.Reason)
284				}
285				if tc.ruleErr && !strings.Contains(f.Reason, "rule 1") {
286					t.Fatalf("reason = %q should name rule 1", f.Reason)
287				}
288				if !strings.Contains(f.Reason, tc.want) {
289					t.Fatalf("reason = %q, want substring %q", f.Reason, tc.want)
290				}
291			})
292		}
293	
294		// A bad rule on a later route invalidates the whole config even when a
295		// request would match an earlier, valid route.
296		t.Run("bad rule located on an unhit route", func(t *testing.T) {
297			src := `{"routes":[
298			  {"id":"hit","methods":["*"],"pathPrefix":"/","upstream":"http://h"},
299			  {"id":"miss","methods":["GET"],"pathPrefix":"/x","upstream":"http://h2","queryTransforms":[
300			    {"op":"set","name":"a","value":"1"},
301			    {"op":"frob","name":"a","value":"1"}
302			  ]}
303			]}`
304			_, f := ParseConfig([]byte(src))
305			if f == nil || f.Code != "invalid_config" {
306				t.Fatalf("got %+v, want invalid_config", f)
307			}
308			for _, want := range []string{"route 2", `"miss"`, "rule 2", "unknown op"} {
309				if !strings.Contains(f.Reason, want) {
310					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
311				}
312			}
313		})
314	
315		// Rule index of a later rule on the first route.
316		t.Run("second rule index reported", func(t *testing.T) {
317			src := `{"routes":[{` + good + `,"queryTransforms":[
318			  {"op":"set","name":"a","value":"1"},
319			  {"op":"remove","name":"a","value":""}
320			]}]}`
321			_, f := ParseConfig([]byte(src))
322			if f == nil || !strings.Contains(f.Reason, "rule 2") {
323				t.Fatalf("got %+v, want reason naming rule 2", f)
324			}
325		})
326	}
327	
328	func TestQueryTransformOnlyAppliedAfterMatching(t *testing.T) {
329		// Transforms must not influence matching or conflict resolution, and a
330		// transform on a losing route is not executed.
331		cfg := mustConfig(t, `{"routes":[
332		  {"id":"wide","methods":["*"],"pathPrefix":"/x","upstream":"http://w",
333		   "queryTransforms":[{"op":"set","name":"from","value":"wildcard"}]},
334		  {"id":"get","methods":["GET"],"pathPrefix":"/x","upstream":"http://g",
335		   "queryTransforms":[{"op":"set","name":"from","value":"concrete"}]}
336		]}`)
337		res := resolveJSON(t, cfg, `{"method":"GET","target":"/x/1?a=1"}`)
338		if res.RouteID != "get" || res.UpstreamURL != "http://g/1?a=1&from=concrete" {
339			t.Fatalf("got %+v", res)
340		}
341	}
